651	  string page_token = 3 [(google.api.field_behavior) = OPTIONAL];
652	}
653	
654	message ListPersonalAccessTokensResponse {
655	  // The list of personal access tokens.
656	  repeated PersonalAccessToken personal_access_tokens = 1;
657	
658	  // A token for the next page of results.
659	  string next_page_token = 2;
660	}
661	
662	message CreatePersonalAccessTokenRequest {
663	  // Required. The parent resource where this token will be created.
664	  // Format: users/{user}
665	  string parent = 1 [
666	    (google.api.field_behavior) = REQUIRED,
667	    (google.api.resource_reference) = {type: "memos.api.v1/User"}
668	  ];
669	
670	  // Optional. Description of the personal access token.
671	  string description = 2 [(google.api.field_behavior) = OPTIONAL];
672	
673	  // Optional. Expiration duration in days (0 = never expires).
674	  int32 expires_in_days = 3 [(google.api.field_behavior) = OPTIONAL];
675	}
676	
677	message CreatePersonalAccessTokenResponse {
678	  // The personal access token metadata.
679	  PersonalAccessToken personal_access_token = 1;
680	
681	  // The actual token value - only returned on creation.
682	  // This is the only time the token value will be visible.
683	  string token = 2;
684	}
685	
686	message DeletePersonalAccessTokenRequest {
687	  // Required. The resource name of the personal access token to delete.
688	  // Format: users/{user}/personalAccessTokens/{personal_access_token}
689	  string name = 1 [
690	    (google.api.field_behavior) = REQUIRED,
691	    (google.api.resource_reference) = {type: "memos.api.v1/PersonalAccessToken"}
692	  ];
693	}
694	
695	// UserWebhook represents a webhook owned by a user.
696	message UserWebhook {
697	  // The name of the webhook.
698	  // Format: users/{user}/webhooks/{webhook}
699	  string name = 1;
700	
701	  // The URL to send the webhook to.
702	  string url = 2;
703	
704	  // Optional. Human-readable name for the webhook.
705	  string display_name = 3;
706	
707	  // The creation time of the webhook.
708	  google.protobuf.Timestamp create_time = 4 [(google.api.field_behavior) = OUTPUT_ONLY];
709	
710	  // The last update time of the webhook.
711	  google.protobuf.Timestamp update_time = 5 [(google.api.field_behavior) = OUTPUT_ONLY];
712	
713	  // Optional. Signing secret used to HMAC-SHA256 sign the webhook request body.
714	  // This field is input-only; it is never returned in responses.
715	  string signing_secret = 6 [(google.api.field_behavior) = INPUT_ONLY];
716	
717	  // Whether a signing secret is configured for this webhook.
718	  bool signing_secret_set = 7 [(google.api.field_behavior) = OUTPUT_ONLY];
719	}
720	
721	message ListUserWebhooksRequest {
722	  // The parent user resource.
723	  // Format: users/{user}
724	  string parent = 1 [(google.api.field_behavior) = REQUIRED];
725	}
726	
727	message ListUserWebhooksResponse {
728	  // The list of webhooks.
729	  repeated UserWebhook webhooks = 1;
730	}
731	
732	message CreateUserWebhookRequest {
733	  // The parent user resource.
734	  // Format: users/{user}
735	  string parent = 1 [(google.api.field_behavior) = REQUIRED];
736	
737	  // The webhook to create.
738	  UserWebhook webhook = 2 [(google.api.field_behavior) = REQUIRED];
739	}
740	
741	message UpdateUserWebhookRequest {
742	  // The webhook to update.
743	  UserWebhook webhook = 1 [(google.api.field_behavior) = REQUIRED];
744	
745	  // The list of fields to update.
746	  google.protobuf.FieldMask update_mask = 2;
747	}
748	
749	message DeleteUserWebhookRequest {
750	  // The name of the webhook to delete.
751	  // Format: users/{user}/webhooks/{webhook}
752	  string name = 1 [(google.api.field_behavior) = REQUIRED];
753	}
754	
755	message GetUserWebhookSigningSecretRequest {
756	  // The name of the webhook whose signing secret to reveal.
757	  // Format: users/{user}/webhooks/{webhook}
758	  string name = 1 [(google.api.field_behavior) = REQUIRED];
759	}
760	
761	message GetUserWebhookSigningSecretResponse {
762	  // The signing secret, in the Standard Webhooks "whsec_<base64>" form.
763	  string signing_secret = 1;
764	}
765	
766	message UserNotification {
767	  option (google.api.resource) = {
768	    type: "memos.api.v1/UserNotification"
769	    pattern: "users/{user}/notifications/{notification}"
770	    name_field: "name"
771	    singular: "notification"
772	    plural: "notifications"
773	  };
774	
775	  // The resource name of the notification.
776	  // Format: users/{user}/notifications/{notification}
777	  string name = 1 [
778	    (google.api.field_behavior) = OUTPUT_ONLY,
779	    (google.api.field_behavior) = IDENTIFIER
780	  ];
781	
782	  // The sender of the notification.
783	  // Format: users/{user}
784	  string sender = 2 [
785	    (google.api.field_behavior) = OUTPUT_ONLY,
786	    (google.api.resource_reference) = {type: "memos.api.v1/User"}
787	  ];
788	
789	  // The sender user details.
790	  User sender_user = 8 [(google.api.field_behavior) = OUTPUT_ONLY];
791	
792	  // The status of the notification.
793	  Status status = 3 [(google.api.field_behavior) = OPTIONAL];
794	
795	  // The creation timestamp.
796	  google.protobuf.Timestamp create_time = 4 [(google.api.field_behavior) = OUTPUT_ONLY];
797	
798	  // The type of the notification.
799	  Type type = 5 [(google.api.field_behavior) = OUTPUT_ONLY];
800	
801	  oneof payload {
802	    MemoCommentPayload memo_comment = 6 [(google.api.field_behavior) = OUTPUT_ONLY];
803	    MemoMentionPayload memo_mention = 7 [(google.api.field_behavior) = OUTPUT_ONLY];
804	  }
805	
806	  message MemoCommentPayload {
807	    // The memo name of comment.
808	    // Format: memos/{memo}
809	    string memo = 1;
810	
811	    // The name of related memo.
812	    // Format: memos/{memo}
813	    string related_memo = 2;
814	
815	    // Preview text of the comment memo.
816	    string memo_snippet = 3;
817	
818	    // Preview text of the related memo.
819	    string related_memo_snippet = 4;
820	  }
821	
822	  message MemoMentionPayload {
823	    // The memo that contains the mention.
824	    // Format: memos/{memo}
825	    string memo = 1;
826	
827	    // The related parent memo when the mention was created in a comment.
828	    // Format: memos/{memo}
829	    string related_memo = 2;
830	
831	    // Preview text of the memo that contains the mention.
832	    string memo_snippet = 3;
833	
834	    // Preview text of the related parent memo.
835	    string related_memo_snippet = 4;
836	  }
837	
838	  enum Status {
839	    STATUS_UNSPECIFIED = 0;
840	    UNREAD = 1;
841	    ARCHIVED = 2;
842	  }
843	
844	  enum Type {
845	    TYPE_UNSPECIFIED = 0;
846	    MEMO_COMMENT = 1;
847	    MEMO_MENTION = 2;
848	  }
849	}
850	
851	message ListUserNotificationsRequest {
852	  // The parent user resource.
853	  // Format: users/{user}
854	  string parent = 1 [
855	    (google.api.field_behavior) = REQUIRED,
856	    (google.api.resource_reference) = {type: "memos.api.v1/User"}
857	  ];
858	
859	  int32 page_size = 2 [(google.api.field_behavior) = OPTIONAL];
860	  string page_token = 3 [(google.api.field_behavior) = OPTIONAL];
861	  string filter = 4 [(google.api.field_behavior) = OPTIONAL];
862	}
863	
864	message ListUserNotificationsResponse {
865	  repeated UserNotification notifications = 1;
866	  string next_page_token = 2;
867	}
868	
869	message UpdateUserNotificationRequest {
870	  UserNotification notification = 1 [(google.api.field_behavior) = REQUIRED];
871	  google.protobuf.FieldMask update_mask = 2 [(google.api.field_behavior) = REQUIRED];
872	}
873	
874	message DeleteUserNotificationRequest {
875	  // Format: users/{user}/notifications/{notification}
876	  string name = 1 [
877	    (google.api.field_behavior) = REQUIRED,
878	    (google.api.resource_reference) = {type: "memos.api.v1/UserNotification"}
879	  ];
880	}
